  "src.sdgs": { en: "UN Sustainable Development Goals and targets, with a written reason for every link.", ms: "Matlamat dan sasaran Pembangunan Mampan PBB, dengan sebab bertulis bagi setiap kaitan.", zh: "联合国可持续发展目标及具体目标，每项关联都有书面理由。" },
