  "src.prices": { en: "from each provider's own page, with the date we checked; ask the provider before enrolling.", ms: "daripada halaman setiap penyedia, dengan tarikh kami menyemaknya; tanya penyedia sebelum mendaftar.", zh: "来自各课程方的官方页面，并注明核对日期；报名前请向课程方确认。" },
  "src.trendT": { en: "Trend refresh", ms: "Kemas kini trend", zh: "趋势刷新" },
  "src.trend1": { en: "arXiv (or OpenAlex) paper counts, Hacker News “Who is hiring?” posts, and Malaysian employment by occupation group from the", ms: "bilangan kertas arXiv (atau OpenAlex), hantaran “Who is hiring?” Hacker News, dan pekerjaan di Malaysia mengikut kumpulan pekerjaan daripada", zh: "arXiv（或 OpenAlex）论文数量、Hacker News “Who is hiring?” 招聘帖，以及来自" },
  "src.opendosm": { en: "OpenDOSM public API", ms: "API awam OpenDOSM", zh: "OpenDOSM 公开 API" },
  "src.trend2": { en: "(Salaries & Wages Survey, latest year vs three years earlier). Raw counts are kept in", ms: "(Survei Gaji & Upah, tahun terkini berbanding tiga tahun sebelumnya). Bilangan mentah disimpan dalam", zh: "的马来西亚各职业类别就业人数（薪资调查，最新一年对比三年前）。原始数据保存在" },
  "src.evidenceT": { en: "Skill evidence", ms: "Bukti kemahiran", zh: "技能证据" },
  "src.evidence": { en: "current Malaysian job ads found by Gemini with Google Search grounding. Each role's ads and quotes are checked and approved by a named reviewer before they count; the role page shows them.", ms: "iklan jawatan Malaysia terkini yang ditemui oleh Gemini dengan carian Google. Iklan dan petikan setiap peranan disemak dan diluluskan oleh penyemak bernama sebelum dikira; halaman peranan memaparkannya.", zh: "由 Gemini 结合 Google 搜索找到的马来西亚最新招聘广告。每个职位的广告和引文须经署名审核人核对批准后才计入；职位页面会显示它们。" },
  "src.emerging": { en: "new job titles found by Gemini with Google Search grounding, one per AI capability we track, each with its quoted sources and approved by a named reviewer. Shown as a prediction and never ranked.", ms: "jawatan baharu yang ditemui oleh Gemini dengan carian Google, satu bagi setiap keupayaan AI yang kami jejaki, masing-masing dengan sumber yang dipetik dan diluluskan oleh penyemak bernama. Dipaparkan sebagai ramalan dan tidak disusun mengikut kedudukan.", zh: "由 Gemini 结合 Google 搜索找到的新职位名称，我们追踪的每种 AI 能力各一个，均附引用来源并经署名审核人批准。作为预测显示，不参与排名。" },
  "src.day": { en: "written by Gemini from our own data only (O*NET tasks, work context, main skills, DOSM pay group and SDG reason), committed for team review. A richer version using approved Malaysian job ads replaces it only after a named reviewer approves it.", ms: "ditulis oleh Gemini daripada data kami sahaja (tugasan O*NET, suasana kerja, kemahiran utama, kumpulan gaji DOSM dan sebab SDG), untuk disemak pasukan. Versi lebih lengkap yang menggunakan iklan jawatan Malaysia yang diluluskan hanya menggantikannya selepas diluluskan oleh penyemak bernama.", zh: "由 Gemini 仅根据我们的数据撰写（O*NET 任务、工作环境、主要技能、DOSM 薪资类别和 SDG 理由），供团队审核。使用已批准的马来西亚招聘广告的更详细版本，须经署名审核人批准后才会替换。" },
  "src.payT": { en: "Pay", ms: "Gaji", zh: "薪资" },
  "src.pay1": { en: "median monthly salaries by MASCO occupation group from the", ms: "gaji bulanan penengah mengikut kumpulan pekerjaan MASCO daripada", zh: "按 MASCO 职业类别统计的月薪中位数，来自" },
  "src.pay2": { en: "(table A10). These are group medians, not job offers.", ms: "(jadual A10). Ini ialah penengah kumpulan, bukan tawaran kerja.", zh: "（表 A10）。这些是职业类别中位数，并非工作报价。" },
  "src.help": { en: "Help us check it", ms: "Bantu kami menyemaknya", zh: "帮我们核查" },
  "src.helpSub": { en: "Native speakers, teammates and career counsellors can check our translations, mark the test CVs and review the demo pathways in the review kit.", ms: "Penutur asli, rakan sepasukan dan kaunselor kerjaya boleh menyemak terjemahan kami, menilai CV ujian dan menyemak laluan demo dalam kit semakan.", zh: "母语人士、队友和职业辅导员可以在审核工具中检查我们的翻译、评分测试简历并审阅示范路径。" },
  "src.openKit": { en: "Open the review kit", ms: "Buka kit semakan", zh: "打开审核工具" },
  "fc.gone": { en: "This Future Card no longer exists. Its owner may have deleted their profile.", ms: "Kad Masa Depan ini tidak wujud lagi. Pemiliknya mungkin telah memadam profilnya.", zh: "这张未来卡片已不存在，持有人可能已删除个人资料。" },
