  "fc.range": { en: "Range across scenarios: {low}% to {high}% jobs. An estimate, not a prediction.", ms: "Julat merentas senario: {low}% hingga {high}% pekerjaan. Anggaran, bukan ramalan.", zh: "各情景下的范围：就业 {low}% 至 {high}%。这是估计，不是预言。" },
