  "fc.source": { en: "Outlook source: {id}, imported {date}. Card created {created}; figures update when the data does.", ms: "Sumber prospek: {id}, diimport {date}. Kad dibuat {created}; angka dikemas kini apabila data berubah.", zh: "前景来源：{id}，{date} 导入。卡片创建于 {created}；数据更新时数字也会更新。" },
