  "xr.own": { en: "your own setting", ms: "tetapan anda sendiri", zh: "您自己的设定" },
  "xr.scaled": { en: "Scaled to {year}", ms: "Diskalakan ke {year}", zh: "按 {year} 年缩放" },
  "xr.noRefresh": { en: "no trend refresh approved yet, so this adds nothing", ms: "belum ada kemas kini trend yang diluluskan, jadi ini tidak menambah apa-apa", zh: "尚未批准趋势刷新，因此此项不增加任何数值" },
  "home.helloName": { en: "{g}, {name}.", ms: "{g}, {name}.", zh: "{g}，{name}。" },
  "cal.title": { en: "Plan it in my calendar", ms: "Rancang dalam kalendar saya", zh: "加入我的日历" },
  "cal.sub": { en: "Turn the courses you haven't finished into weekly study sessions, one course after another. The file opens in Google, Outlook or Apple Calendar.", ms: "Jadikan kursus yang belum anda tamatkan sebagai sesi belajar mingguan, satu kursus demi satu. Fail ini boleh dibuka dalam Google, Outlook atau Apple Calendar.", zh: "把尚未完成的课程变成每周的学习时段，一门接一门。文件可在 Google、Outlook 或 Apple 日历中打开。" },
  "cal.days": { en: "Study on", ms: "Belajar pada", zh: "学习日" },
  "cal.sun": { en: "Sun", ms: "Ahd", zh: "周日" },
  "cal.mon": { en: "Mon", ms: "Isn", zh: "周一" },
  "cal.tue": { en: "Tue", ms: "Sel", zh: "周二" },
  "cal.wed": { en: "Wed", ms: "Rab", zh: "周三" },
