  "cal.fri": { en: "Fri", ms: "Jum", zh: "周五" },
  "cal.sat": { en: "Sat", ms: "Sab", zh: "周六" },
  "cal.length": { en: "Each session", ms: "Setiap sesi", zh: "每次时长" },
  "cal.hours": { en: "{n} h", ms: "{n} jam", zh: "{n} 小时" },
  "cal.time": { en: "Start time", ms: "Masa mula", zh: "开始时间" },
  "cal.summary": { en: "{n} sessions for {courses} courses; you would finish around {date}.", ms: "{n} sesi untuk {courses} kursus; anda akan selesai sekitar {date}.", zh: "{courses} 门课程共 {n} 次学习，预计在 {date} 左右完成。" },
  "cal.pickDay": { en: "Pick at least one day.", ms: "Pilih sekurang-kurangnya satu hari.", zh: "请至少选择一天。" },
  "cal.download": { en: "Download calendar file (.ics)", ms: "Muat turun fail kalendar (.ics)", zh: "下载日历文件（.ics）" },
  "cal.note": { en: "Made in your browser; nothing is sent to Laluan. Course hours are the providers' estimates.", ms: "Dibuat dalam pelayar anda; tiada apa dihantar kepada Laluan. Jam kursus ialah anggaran penyedia.", zh: "在您的浏览器中生成，不会发送给 Laluan。课程时数为课程方的估计。" },
  "cal.count": { en: "session {i} of {n}", ms: "sesi {i} daripada {n}", zh: "第 {i}/{n} 次" },
