  "req.route": { en: "How to get it:", ms: "Cara mendapatkannya:", zh: "取得途径：" },
  "req.coursesNote": { en: "The courses in Laluan build the skills; they do not replace this qualification. Plan for it first.", ms: "Kursus dalam Laluan membina kemahiran; ia tidak menggantikan kelayakan ini. Rancang untuknya dahulu.", zh: "Laluan 中的课程用于培养技能，不能替代这项资格。请先为此做好规划。" },
  "req.usually": { en: "Employers usually ask for", ms: "Majikan biasanya meminta", zh: "雇主通常要求" },
  "req.usualNote": { en: "Usual for this occupation group, not a rule: skills can also come from training and experience.", ms: "Lazim bagi kumpulan pekerjaan ini, bukan peraturan: kemahiran juga boleh diperoleh melalui latihan dan pengalaman.", zh: "这是该职业类别的常见要求，并非硬性规定：技能也可以通过培训和经验获得。" },
  "req.etaPlus": { en: "+ {time} for the licence", ms: "+ {time} untuk lesen", zh: "+ 取得执照{time}" },
