  "req.adsShown": { en: "From {n} Malaysian job ads read on {date}: see what they say", ms: "Daripada {n} iklan jawatan Malaysia yang dibaca pada {date}: lihat apa yang dinyatakan", zh: "来自 {date} 读取的 {n} 则马来西亚招聘广告：查看原文" },
  "req.noAds": { en: "Too few current job ads to check against.", ms: "Terlalu sedikit iklan jawatan semasa untuk disemak.", zh: "目前的招聘广告太少，无法核对。" },
  "req.lvl.SPM": { en: "SPM", ms: "SPM", zh: "SPM" },
