  "card.startWith": { en: "Start with {role}: it already uses part of what this role needs.", ms: "Mulakan dengan {role}: ia sudah menggunakan sebahagian daripada apa yang diperlukan oleh peranan ini.", zh: "可先从“{role}”开始：它已用到此职位所需的部分技能。" },
