  "route.badge": { en: "Shortest route", ms: "Laluan terpendek", zh: "最短路线" },
  "route.text": { en: "about {h} hours of courses ({n}% skill fit today), compared with about {topH} hours for {top}.", ms: "kira-kira {h} jam kursus ({n}% padanan kemahiran hari ini), berbanding kira-kira {topH} jam untuk {top}.", zh: "约 {h} 小时课程（目前技能匹配 {n}%），而“{top}”约需 {topH} 小时。" },
  "wf.inPlace": { en: "Option 1 · Upskill in place", ms: "Pilihan 1 · Tingkatkan kemahiran di tempat", zh: "选项 1 · 原岗位提升" },
  "wf.inPlaceSub": { en: "Each group in a declining role keeps its job and learns the AI skills that are changing it. Hours count every skill they already have.", ms: "Setiap kumpulan dalam peranan yang menurun mengekalkan pekerjaannya dan mempelajari kemahiran AI yang sedang mengubahnya. Jam mengambil kira setiap kemahiran yang sudah mereka ada.", zh: "处于下降职位的每个群体保留原岗位，学习正在改变这份工作的 AI 技能。时数已计入他们已有的每项技能。" },
  "wf.getAheadSub": { en: "Not declining under this scenario, but AI is likely to automate 40% or more of their tasks. Upskilling now costs less than reskilling later.", ms: "Tidak menurun dalam senario ini, tetapi AI mungkin mengautomasikan 40% atau lebih tugasan mereka. Meningkatkan kemahiran sekarang lebih murah daripada melatih semula kemudian.", zh: "在此情景下没有下降，但 AI 可能自动化其中 40% 或更多的任务。现在提升技能比日后再培训成本更低。" },
  "deg.title": { en: "Start from your degree", ms: "Mulakan daripada ijazah anda", zh: "从您的学位开始" },
  "deg.sub": { en: "Pick your programme and we suggest the skills it usually teaches. You confirm each one on the next screen, and anything from your CV or the list is added to them.", ms: "Pilih program anda dan kami cadangkan kemahiran yang biasanya diajar. Anda mengesahkan setiap satu di skrin seterusnya, dan apa-apa daripada CV atau senarai anda akan ditambah.", zh: "选择您的专业，我们会建议该专业通常教授的技能。您会在下一页逐项确认，来自简历或列表的技能也会一并加入。" },
  "deg.label": { en: "Your programme", ms: "Program anda", zh: "您的专业" },
  "deg.choose": { en: "Choose a programme (optional)", ms: "Pilih program (pilihan)", zh: "选择专业（可选）" },
  "deg.usually": { en: "This programme usually teaches:", ms: "Program ini biasanya mengajar:", zh: "这个专业通常教授：" },
  "deg.note": { en: "Suggested from typical Malaysian programmes and checked by our team. Untick anything you didn't really learn.", ms: "Dicadangkan daripada program biasa di Malaysia dan disemak oleh pasukan kami. Nyahtanda apa-apa yang tidak benar-benar anda pelajari.", zh: "根据马来西亚常见专业的课程建议，并经团队审核。没有真正学过的请取消勾选。" },
  "class.byProgramme": { en: "By programme", ms: "Mengikut program", zh: "按专业" },
  "class.byProgrammeSub": { en: "Where each programme's students fit best and the gaps an add-on course could close. Programmes with fewer than 3 students are left out.", ms: "Di mana pelajar setiap program paling sesuai dan jurang yang boleh ditutup dengan kursus tambahan. Program dengan kurang daripada 3 pelajar tidak dipaparkan.", zh: "各专业学生最适合的职位，以及一门附加课程可以弥补的差距。少于 3 名学生的专业不显示。" },
  "class.programme": { en: "Programme", ms: "Program", zh: "专业" },
  "op.find": { en: "Find current openings for {role} in Malaysia", ms: "Cari jawatan kosong terkini untuk {role} di Malaysia", zh: "查找马来西亚目前招聘“{role}”的职位" },
  "op.searching": { en: "Searching Malaysian job ads (about a minute)…", ms: "Mencari iklan jawatan di Malaysia (kira-kira seminit)…", zh: "正在搜索马来西亚招聘广告（约一分钟）…" },
  "op.failed": { en: "The search didn't work. Try again later.", ms: "Carian tidak berjaya. Cuba lagi nanti.", zh: "搜索失败，请稍后再试。" },
  "op.title": { en: "Current openings found on {date}", ms: "Jawatan kosong terkini ditemui pada {date}", zh: "{date} 找到的在招职位" },
  "op.none": { en: "No Malaysian job ads came back this time. Try the job sites above.", ms: "Tiada iklan jawatan Malaysia ditemui kali ini. Cuba laman kerja di atas.", zh: "这次没有找到马来西亚的招聘广告，请试试上方的求职网站。" },
  "op.otherPages": { en: "Also found {n} other pages that are not job ads.", ms: "Turut ditemui {n} halaman lain yang bukan iklan jawatan.", zh: "另外找到 {n} 个非招聘广告的页面。" },
  "op.note": { en: "Current Malaysian job ads read just now from freehire.me (mostly JobStreet), each with its own link; not checked by our team and never used in your ranking. Ads close quickly: check the date on the employer's page before you apply.", ms: "Iklan kerja Malaysia terkini yang baru dibaca daripada freehire.me (kebanyakannya JobStreet), setiap satu dengan pautannya sendiri; tidak disemak oleh pasukan kami dan tidak digunakan dalam kedudukan anda. Iklan cepat ditutup: semak tarikh di halaman majikan sebelum memohon.", zh: "刚从 freehire.me（主要来自 JobStreet）读取的马来西亚最新招聘广告，每则附原始链接；未经团队审核，也不会用于您的排名。招聘广告很快会关闭：申请前请在雇主页面核对日期。" },
