  "src.helpBody": { en: "Native speakers, teammates and career counsellors can check our translations, mark the test CVs and review the demo pathways in the review kit.", ms: "Penutur asli, rakan sepasukan dan kaunselor kerjaya boleh menyemak terjemahan kami, menanda CV ujian dan menyemak laluan demo dalam kit semakan.", zh: "母语人士、队友和职业顾问可以在审阅工具中核对我们的翻译、评分测试简历并审阅演示路径。" },
  "src.exposureT": { en: "Published AI exposure", ms: "Pendedahan AI yang diterbitkan", zh: "已发表的 AI 影响研究" },
  "src.exposure": { en: "Matched to each role by occupation code and shown next to Laluan's own estimate for comparison; never used in the ranking. The Malaysia AI-use figures come from the same index.", ms: "Dipadankan kepada setiap peranan melalui kod pekerjaan dan dipaparkan bersama anggaran Laluan sebagai perbandingan; tidak pernah digunakan dalam kedudukan. Angka penggunaan AI Malaysia datang daripada indeks yang sama.", zh: "按职业代码与每个职位匹配，并与 Laluan 自己的估算并列比较；从不用于排名。马来西亚的 AI 使用数据也来自同一指数。" },
  "src.mycolT": { en: "Critical occupations", ms: "Pekerjaan kritikal", zh: "紧缺职业" },
  "src.mycol": { en: "Matched by the job titles employers nominated, with the report page. Links only; no endorsement implied.", ms: "Dipadankan melalui jawatan yang dicalonkan majikan, dengan halaman laporan. Pautan sahaja; tiada pengendorsan.", zh: "按雇主提名的职位名称匹配，并注明报告页码。仅为链接，不代表任何背书。" },
  "src.postingsT": { en: "Malaysian job postings", ms: "Iklan jawatan Malaysia", zh: "马来西亚招聘信息" },
  "src.postings": { en: "An open-source job search engine: skill mentions in Malaysian postings for the trend refresh, and the newest openings on each role page, linked to the original posting.", ms: "Enjin carian kerja sumber terbuka: sebutan kemahiran dalam iklan Malaysia untuk kemas kini trend, dan jawatan terkini pada setiap halaman peranan, dipautkan kepada iklan asal.", zh: "开源职位搜索引擎：用于趋势更新的马来西亚招聘技能提及，以及每个职位页上最新的职缺（链接到原始招聘）。" },
