  "unsub.title": { en: "You're unsubscribed", ms: "Anda telah berhenti melanggan", zh: "你已退订" },
  "unsub.all": { en: "You won't get any more emails from Laluan, and your email address is no longer kept. You can turn emails back on in My profile.", ms: "Anda tidak akan menerima e-mel lagi daripada Laluan, dan alamat e-mel anda tidak lagi disimpan. Anda boleh menghidupkan semula e-mel dalam Profil saya.", zh: "你不会再收到 Laluan 的邮件，你的电邮地址也不再保留。你可以在“我的资料”中重新开启。" },
  "unsub.alerts": { en: "Job alerts are off. Your weekly summary, if you have one, still comes on Mondays.", ms: "Amaran kerja dimatikan. Ringkasan mingguan anda, jika ada, masih dihantar setiap Isnin.", zh: "职位提醒已关闭。如果你订阅了每周摘要，仍会在每周一收到。" },
  "unsub.failedTitle": { en: "That link didn't work", ms: "Pautan itu tidak berfungsi", zh: "该链接无效" },
  "unsub.failed": { en: "This unsubscribe link isn't valid. Log in and turn emails off in My profile, or reply to the email.", ms: "Pautan berhenti langganan ini tidak sah. Log masuk dan matikan e-mel dalam Profil saya, atau balas e-mel tersebut.", zh: "此退订链接无效。请登录并在“我的资料”中关闭邮件，或直接回复该邮件。" },
  "unsub.open": { en: "Open Laluan", ms: "Buka Laluan", zh: "打开 Laluan" },
  "cls.title": { en: "Career-centre classes", ms: "Kelas pusat kerjaya", zh: "就业中心班级" },
  "cls.sub": { en: "Make a class, share its join code, and follow each student who joins: only their name, destination, readiness, courses finished, skills proven, last active, target date and on-track status.", ms: "Cipta kelas, kongsi kod sertainya, dan ikuti setiap pelajar yang menyertai: hanya nama, destinasi, kesediaan, kursus selesai, kemahiran dibuktikan, aktif terakhir, tarikh sasaran dan status landasan.", zh: "创建班级，分享加入代码，跟进每位加入的学生：只显示姓名、目标、准备度、已完成课程、已证明的技能、最近活动、目标日期和进度状态。" },
  "cls.loginFirst": { en: "Log in with Google to run a class. A Laluan admin then approves you as a counsellor.", ms: "Log masuk dengan Google untuk mengendalikan kelas. Pentadbir Laluan kemudian meluluskan anda sebagai kaunselor.", zh: "使用 Google 登录即可管理班级，之后由 Laluan 管理员批准你成为辅导员。" },
  "cls.yourName": { en: "Your name, as students will see it", ms: "Nama anda, seperti yang dilihat pelajar", zh: "你的名字（学生会看到）" },
  "cls.org": { en: "School, college or university", ms: "Sekolah, kolej atau universiti", zh: "学校、学院或大学" },
  "cls.request": { en: "Ask to be a counsellor", ms: "Mohon menjadi kaunselor", zh: "申请成为辅导员" },
  "cls.pending": { en: "Thanks. A Laluan admin will check and approve your request.", ms: "Terima kasih. Pentadbir Laluan akan menyemak dan meluluskan permohonan anda.", zh: "谢谢。Laluan 管理员会审核并批准你的申请。" },
  "cls.revoked": { en: "Your counsellor access was removed. Contact the Laluan team if this is a mistake.", ms: "Akses kaunselor anda telah dibuang. Hubungi pasukan Laluan jika ini satu kesilapan.", zh: "你的辅导员权限已被撤销。如有误，请联系 Laluan 团队。" },
  "cls.className": { en: "New class name", ms: "Nama kelas baharu", zh: "新班级名称" },
  "cls.create": { en: "Create class", ms: "Cipta kelas", zh: "创建班级" },
  "cls.none": { en: "No classes yet.", ms: "Belum ada kelas.", zh: "还没有班级。" },
  "cls.members": { en: "{n} students", ms: "{n} pelajar", zh: "{n} 名学生" },
  "cls.code": { en: "Join code", ms: "Kod sertai", zh: "加入代码" },
  "err.details": { en: "Technical details (send these to the team)", ms: "Butiran teknikal (hantar kepada pasukan)", zh: "技术细节（请发给团队）" },
  "cls.copied": { en: "Copied", ms: "Disalin", zh: "已复制" },
  "cls.open": { en: "Open", ms: "Buka", zh: "打开" },
  "cls.delete": { en: "Delete class", ms: "Padam kelas", zh: "删除班级" },
  "cls.deleteConfirm": { en: "Delete {name}? Students stay in Laluan, but you will no longer see them.", ms: "Padam {name}? Pelajar kekal dalam Laluan, tetapi anda tidak lagi dapat melihat mereka.", zh: "删除{name}？学生仍会留在 Laluan，但你将无法再看到他们。" },
  "cls.boardNote": { en: "Only what each student agreed to share when they joined. They can leave at any time, and then disappear from this list.", ms: "Hanya apa yang dipersetujui oleh setiap pelajar semasa menyertai. Mereka boleh keluar bila-bila masa, dan kemudian hilang daripada senarai ini.", zh: "只显示每位学生加入时同意分享的内容。他们可以随时退出，退出后会从此列表中消失。" },
  "cls.filter": { en: "Show", ms: "Tunjukkan", zh: "显示" },
  "cls.all": { en: "All ({n})", ms: "Semua ({n})", zh: "全部（{n}）" },
  "cls.noDate": { en: "No target date", ms: "Tiada tarikh sasaran", zh: "未设目标日期" },
  "cls.empty": { en: "No students yet. Share the join code or link.", ms: "Belum ada pelajar. Kongsi kod atau pautan sertai.", zh: "还没有学生。请分享加入代码或链接。" },
  "cls.unnamed": { en: "(no name)", ms: "(tiada nama)", zh: "（未填姓名）" },
