  "cls.studentTitle": { en: "Join a career-centre class", ms: "Sertai kelas pusat kerjaya", zh: "加入就业中心班级" },
  "cls.studentSub": { en: "If your counsellor gave you a code, enter it here. You'll see exactly what they can see before you join, and you can leave at any time.", ms: "Jika kaunselor anda memberi kod, masukkan di sini. Anda akan melihat dengan tepat apa yang boleh mereka lihat sebelum menyertai, dan anda boleh keluar bila-bila masa.", zh: "如果辅导员给了你代码，请在此输入。加入前你会看到他们能看到的具体内容，你也可以随时退出。" },
  "cls.needLogin": { en: "Log in with Google and save your profile to your account to join a class.", ms: "Log masuk dengan Google dan simpan profil anda ke akaun untuk menyertai kelas.", zh: "使用 Google 登录并把资料保存到账户后，才能加入班级。" },
  "cls.find": { en: "Find class", ms: "Cari kelas", zh: "查找班级" },
  "cls.noClass": { en: "No class with that code. Check it with your counsellor.", ms: "Tiada kelas dengan kod itu. Semak dengan kaunselor anda.", zh: "没有使用该代码的班级。请与辅导员核对。" },
  "cls.shareTitle": { en: "If you join, your counsellor will see only:", ms: "Jika anda menyertai, kaunselor anda hanya akan melihat:", zh: "如果你加入，辅导员只能看到：" },
  "cls.notShared": { en: "Never shared: your skill list, survey answers, CV, chats with the coach or interview answers.", ms: "Tidak pernah dikongsi: senarai kemahiran, jawapan tinjauan, CV, perbualan dengan jurulatih atau jawapan temu duga anda.", zh: "永不分享：你的技能清单、问卷回答、简历、与顾问的对话或面试回答。" },
  "cls.join": { en: "Join and share", ms: "Sertai dan kongsi", zh: "加入并分享" },
