  "cls.leaveConfirm": { en: "Leave {name}? Your counsellor stops seeing your progress at once.", ms: "Keluar daripada {name}? Kaunselor anda berhenti melihat kemajuan anda serta-merta.", zh: "退出{name}？辅导员将立即无法再看到你的进度。" },
