  "act.accept": { en: "Accept", ms: "Terima", zh: "接受" },
  "act.decline": { en: "No, thanks", ms: "Tidak, terima kasih", zh: "不用了" },
  "act.markDone": { en: "Mark done", ms: "Tanda selesai", zh: "标记完成" },
  "act.allAnswered": { en: "You've answered everything your counsellor proposed.", ms: "Anda telah menjawab semua cadangan kaunselor anda.", zh: "你已回复辅导员的所有建议。" },
  "act.history": { en: "Answered ({n})", ms: "Telah dijawab ({n})", zh: "已回复（{n}）" },
  "act.note": { en: "Nothing in your plan changes until you accept. A new date or study hours apply at once; the rest become to-dos.", ms: "Tiada apa dalam pelan anda berubah sehingga anda menerimanya. Tarikh atau jam belajar baharu berkuat kuasa serta-merta; yang lain menjadi senarai tugasan.", zh: "在你接受之前，计划不会有任何改变。新的日期或学习时数会立即生效；其余的成为待办事项。" },
  "act.failed": { en: "Couldn't save your answer. Try again.", ms: "Tidak dapat menyimpan jawapan anda. Cuba lagi.", zh: "无法保存你的回复，请重试。" },
