  "exp.totalsOnly": { en: "Totals by role only, never a ranking of people. Estimates for planning, not quotes.", ms: "Jumlah mengikut peranan sahaja, bukan kedudukan individu. Anggaran untuk perancangan, bukan sebut harga.", zh: "仅按职位汇总，绝不对个人排名。用于规划的估算，并非报价。" },
  "class.exportTitle": { en: "Laluan class view", ms: "Paparan kelas Laluan", zh: "Laluan 班级视图" },
  "grant.title": { en: "HRD Corp training-grant plan", ms: "Pelan geran latihan HRD Corp", zh: "HRD Corp 培训补助计划" },
  "grant.sub": { en: "Every course in the moves above, who takes it, the hours and its dated price, to prepare your own HRD Corp application.", ms: "Setiap kursus dalam pergerakan di atas, siapa yang mengambilnya, jam dan harga bertarikh, untuk menyediakan permohonan HRD Corp anda sendiri.", zh: "上方转岗中的每门课程、参加人数、时数及带日期的价格，便于您自行准备 HRD Corp 申请。" },
  "grant.disclaimer": { en: "Laluan does not submit claims. Confirm each price, the training provider's registration and the grant scheme with HRD Corp and the provider before you apply.", ms: "Laluan tidak menghantar tuntutan. Sahkan setiap harga, pendaftaran penyedia latihan dan skim geran dengan HRD Corp dan penyedia sebelum memohon.", zh: "Laluan 不提交申领。申请前请向 HRD Corp 和课程提供方确认每项价格、培训机构的注册情况及补助计划。" },
