  "sw.paySource": { en: "DOSM group medians ({group}, {year}), not a job offer", ms: "Median kumpulan DOSM ({group}, {year}), bukan tawaran kerja", zh: "DOSM 组别中位数（{group}，{year}），并非工作报价" },
