  "sw.setHours": { en: "Set your weekly study hours on Pathway to see the weeks", ms: "Tetapkan jam belajar mingguan di Laluan pembelajaran untuk melihat bilangan minggu", zh: "在学习路径中设置每周学习时数即可看到所需周数" },
