  "sw.certs": { en: "Certificates employers ask for:", ms: "Sijil yang diminta majikan:", zh: "雇主要求的证书：" },
  "sw.ads": { en: "{n} ads", ms: "{n} iklan", zh: "{n} 则广告" },
  "sw.notCounted": { en: "Not counted: time between jobs or a lower starting salary. Malaysia publishes no figure for these, so Laluan does not guess.", ms: "Tidak dikira: masa antara pekerjaan atau gaji permulaan yang lebih rendah. Malaysia tidak menerbitkan angka untuk ini, jadi Laluan tidak meneka.", zh: "未计入：两份工作之间的空档期或较低的起薪。马来西亚没有公布相关数据，因此 Laluan 不作猜测。" },
  "hr.sub": { en: "Save an analysis to compare it with later ones. Only the totals by role are kept, never your file.", ms: "Simpan analisis untuk dibandingkan dengan analisis kemudian. Hanya jumlah mengikut peranan disimpan, bukan fail anda.", zh: "保存分析以便与之后的分析比较。只保留按职位的汇总，绝不保存您的文件。" },
  "hr.loginToSave": { en: "Log in with Google to save analyses and see how your team changes over time.", ms: "Log masuk dengan Google untuk menyimpan analisis dan melihat perubahan pasukan anda dari semasa ke semasa.", zh: "使用 Google 登录即可保存分析，并查看团队随时间的变化。" },
