export type StringKey = keyof typeof STRINGS;

/** t() with {placeholders} filled in, e.g. tf("x", { n: 3 }). */
export function tf(key: StringKey, vars: Record<string, string | number>): string {
  return Object.entries(vars).reduce((text, [k, v]) => text.split(`{${k}}`).join(String(v)), t(key));
}

/** A sentence the backend writes in English and also sends as a key with values: shown as that
 * English in English, and as our translation otherwise. Lists of names are joined, each translated. */
export function tv(key: string, vars: Record<string, unknown> | undefined, english: string): string {
  if (current === "en" || !(key in STRINGS)) return english;
  const shown = Object.fromEntries(Object.entries(vars ?? {}).map(([k, v]) =>
    [k, Array.isArray(v) ? v.map((x) => tr(String(x))).join(", ") : typeof v === "string" ? tr(v) : String(v)]));
  return tf(key as StringKey, shown);
}

// Text that comes from the reference data (role titles, skill names, summaries, scenario and task
// text), keyed by its English wording: AI-drafted BM / 中文 from backend/data/translations.json,
// loaded once from the API. English shows until it loads, or where a text has no translation.
let dataText: Record<string, { ms: string; zh: string }> = {};
export function setDataText(strings: Record<string, { ms: string; zh: string }>) { dataText = strings; }
export function tr(en: string | null | undefined): string {
  if (!en) return en ?? "";
  if (current === "en") return en;
  return dataText[en.trim()]?.[current] || en;
}
export type GlossaryKey = Extract<StringKey, `gl.${string}`>;

/** Every string in every language, for the translation check in the review kit. */
export function allStrings(): { key: string; en: string; ms: string; zh: string }[] {
  return Object.entries(STRINGS).map(([key, v]) => ({ key, ...(v as Record<Lang, string>) }));
}

function initial(): Lang {
  try {
    const saved = localStorage.getItem(KEY);
    if (saved === "en" || saved === "ms" || saved === "zh") return saved;
  } catch { /* private mode */ }
  const nav = (navigator.language || "en").toLowerCase();
  return nav.startsWith("ms") ? "ms" : nav.startsWith("zh") ? "zh" : "en";
}

let current: Lang = initial();

export function getLang(): Lang { return current; }

export function setLang(lang: Lang) {
  current = lang;
  document.documentElement.lang = LANGS.find((l) => l.id === lang)!.htmlLang;
  try { localStorage.setItem(KEY, lang); } catch { /* private mode */ }
}

export function t(key: StringKey): string {
  const entry = STRINGS[key] as Record<Lang, string> | undefined;
  return entry ? entry[current] || entry.en : key;  // an unknown key shows as itself, never crashes
}

setLang(current);

/** A label the server sends in all three languages, in the current one (English fallback). */
export function pick(labels: Record<string, string> | undefined, fallback: string): string {
  return labels?.[current] || fallback;
}

/** "Basic" / "Working" / "Advanced" in the current language. */
export function levelName(level: number): string {
  return level >= 1 && level <= 3 ? t(`lvl.${level}` as StringKey) : "";
}
